import generated from "./git-log.generated.json";

// Generated by scripts/gen-git-log.mjs (predev / prebuild) and committed so a
// fresh clone typechecks before the first build. It is `[]` when the build has
// no repository history. A build refreshes it, so it may go dirty after commits.
export interface GitLogEntry {
  hash: string;
  date: string;
  subject: string;
}

export const gitLog: GitLogEntry[] = generated;
